query FlowItemComments($id: String!, $comments: Int!) {
  issue(id: $id) {
    id identifier title description priority estimate createdAt
  state { name type } assignee { id } parent { identifier }
  labels(first: 100) { nodes { id name parent { name } } } relations { nodes { type relatedIssue { identifier } } }
  inverseRelations { nodes { type issue { identifier } } }
  children { nodes { identifier } }
  team { id key }
  project { id name state status { type } lead { id } }
    comments(first: $comments, orderBy: createdAt) { nodes { id body createdAt user { id } } }
  }
}
